using System;using System.Collections.Generic;using UnityEngine;using Exoduser.UnityPort.Core;
namespace Exoduser.UnityPort {public sealed partial class NativeSkillView {
 readonly List<MeshRenderer> guardianViews=new List<MeshRenderer>();Mesh guardianBallMesh,guardianBladeMesh;public int ActiveGuardianViews{get;private set;}
 static Color GuardianColor(int r,int g,int b,float alpha){return new Color(r/255f,g/255f,b/255f,alpha).linear;}
 void LoadGuardianMeshes(){if(guardianBallMesh!=null)return;var b=new BladeMesh{Mesh=new Mesh{name="원문 보호자 구체3겹"}};BladeEllipse(b,0,0,12,12,GuardianColor(170,68,255,.4f));BladeEllipse(b,0,0,7,7,GuardianColor(204,102,255,.9f));BladeEllipse(b,0,0,3,3,GuardianColor(238,204,255,1));b.Mesh.SetVertices(b.Vertices);b.Mesh.SetColors(b.Colors);b.Mesh.SetTriangles(b.Indices,0);b.Mesh.RecalculateBounds();guardianBallMesh=b.Mesh;
 b=new BladeMesh{Mesh=new Mesh{name="원문 합체 보호자 칼날2겹"}};BladePolygon(b,new double[]{10,0,1,-3,-8,-1.5,-10,0,-8,1.5,1,3},GuardianColor(204,204,204,.85f));BladePolygon(b,new double[]{8,0,2,-1.8,-7,0,2,1.8},GuardianColor(238,238,238,1));b.Mesh.SetVertices(b.Vertices);b.Mesh.SetColors(b.Colors);b.Mesh.SetTriangles(b.Indices,0);b.Mesh.RecalculateBounds();guardianBladeMesh=b.Mesh;}
 void UpdateGuardianViews(Simulation sim){int count=sim.GuardianOrbs.Count;ActiveGuardianViews=count;if(count>0)LoadGuardianMeshes();while(guardianViews.Count<count){var go=new GameObject("웹 악의 보호자 궤도");go.transform.SetParent(parent,false);go.AddComponent<MeshFilter>();var renderer=go.AddComponent<MeshRenderer>();renderer.sharedMaterial=malice;guardianViews.Add(renderer);}bool fused=sim.GuardianFused;double radius=(fused?34:28)+sim.Player.Radius;for(int i=0;i<guardianViews.Count;i++){var renderer=guardianViews[i];renderer.gameObject.SetActive(i<count);if(i>=count)continue;double a=sim.GuardianAngle+Math.PI*2/count*i,x=sim.Player.X+Math.Cos(a)*radius,y=sim.Player.Y+Math.Sin(a)*radius;renderer.GetComponent<MeshFilter>().sharedMesh=fused?guardianBladeMesh:guardianBallMesh;renderer.transform.position=NativeRemodel3D.Point(x,y);renderer.transform.rotation=(NativeRemodel3D.Active?Quaternion.Euler(NativeRemodel3D.Pitch*Mathf.Rad2Deg,0,0):Quaternion.identity)*Quaternion.Euler(0,0,fused?-(float)(a+Math.PI/2)*Mathf.Rad2Deg:0);renderer.sortingOrder=(int)y+1;}}
 void ResetGuardianViews(){foreach(var renderer in guardianViews)if(renderer!=null)UnityEngine.Object.Destroy(renderer.gameObject);guardianViews.Clear();if(guardianBallMesh!=null)UnityEngine.Object.Destroy(guardianBallMesh);if(guardianBladeMesh!=null)UnityEngine.Object.Destroy(guardianBladeMesh);guardianBallMesh=guardianBladeMesh=null;ActiveGuardianViews=0;}
}}
